class Solution {
  public int shortestPath(int n, int[][] edges, String labels, int k) {
    int[] head = new int[n], next = new int[edges.length];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < edges.length; i++) {
      next[i] = head[edges[i][0]];
      head[edges[i][0]] = i;
    }
    long INF = Long.MAX_VALUE / 4;
    long[] dist = new long[n * (k + 1)];
    java.util.Arrays.fill(dist, INF);
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    dist[1] = 0;
    pq.add(new long[] {0, 1});
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int state = (int) top[1];
      if (top[0] > dist[state]) continue;
      int u = state / (k + 1), run = state % (k + 1);
      if (u == n - 1) return (int) top[0];
      for (int e = head[u]; e >= 0; e = next[e]) {
        int v = edges[e][1];
        int nr = labels.charAt(v) == labels.charAt(u) ? run + 1 : 1;
        if (nr > k) continue;
        int ns = v * (k + 1) + nr;
        long nd = top[0] + edges[e][2];
        if (nd < dist[ns]) {
          dist[ns] = nd;
          pq.add(new long[] {nd, ns});
        }
      }
    }
    return -1;
  }
}
